package br.com.tapeteskalke.service; import br.com.tapeteskalke.dto.FuncionarioDtos.*; import br.com.tapeteskalke.entity.*; import br.com.tapeteskalke.exception.*; import br.com.tapeteskalke.repository.*; import br.com.tapeteskalke.security.CurrentUser; import br.com.tapeteskalke.util.Normalizer; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class FuncionarioService { private final FuncionarioRepository repo; private final CargoRepository cargos; private final AuditService audit; private final PermissionService permissions; private final CurrentUser current; public FuncionarioService(FuncionarioRepository repo,CargoRepository cargos,AuditService audit,PermissionService permissions,CurrentUser current){this.repo=repo;this.cargos=cargos;this.audit=audit;this.permissions=permissions;this.current=current;} @Transactional(readOnly=true) public List<Response> list(){return repo.activeList().stream().map(this::response).toList();} @Transactional(readOnly=true) public Response get(String id){return response(active(id));} @Transactional public Response create(Request r){permissions.action("funcionarios_criar");var f=new Funcionario();copy(f,r);audit.created(f);return response(repo.save(f));} @Transactional public Response update(String id,Request r){permissions.action("funcionarios_editar");var f=active(id);copy(f,r);audit.changed(f);return response(f);} @Transactional public void delete(String id){permissions.action("funcionarios_excluir");var f=active(id);f.setAtivo(false);f.setDeletedAt(OffsetDateTime.now(ZoneOffset.UTC));f.setAtivo(false);f.setDeletedBy(audit.userId());audit.changed(f);} private Funcionario active(String id){return repo.findById(id).filter(f->f.getDeletedAt()==null).orElseThrow(()->new ResourceNotFoundException("Funcionário",id));} private void copy(Funcionario f,Request r){f.setNome(r.nome().trim());f.setTelefone(Normalizer.digits(r.telefone()));f.setEmail(Normalizer.blankToNull(r.email()));f.setEndereco(Normalizer.blankToNull(r.endereco()));if(current.hasRole("DONO")||current.hasRole("GERENTE"))f.setSalario(r.salario());f.setDataContratacao(r.dataContratacao());if(r.status()!=null)f.setStatus(r.status());f.setCargo(cargos.findById(r.cargoId()).or(()->cargos.findByCodigo(r.cargoId())).orElseThrow(()->new ResourceNotFoundException("Cargo",r.cargoId())));f.setObservacoes(r.observacoes());} private Response response(Funcionario f){boolean salary=current.hasRole("DONO")||current.hasRole("GERENTE");return new Response(f.getId(),f.getNome(),f.getTelefone(),f.getEmail(),f.getCargo().getCodigo(),f.getStatus(),f.getDataContratacao(),salary?f.getSalario():null,f.getEndereco(),f.getObservacoes());} }